import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    if not data or not isinstance(data, list):
        raise ValueError("Empty or invalid JSON data")
    validated_data = []
    for item in data:
        if not isinstance(item.get("Country"), str) or not isinstance(item.get("Population"), (int, float)):
            raise ValueError("Invalid country name or population type")
        if item["Population"] < 0:
            raise ValueError("Population cannot be negative")
        validated_data.append({
            "Country": item["Country"],
            "Population": math.floor(item["Population"])
        })
    df = pd.DataFrame(validated_data, columns=["Country", "Population"])
    output_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(output_path, index=False)
    except Exception:
        raise IOError("Failed to write CSV file")
    return output_path, df
